  'fluence': ['אנרגיה ליחידת שטח בפולס לייזר, ב-J/cm². חומר מוסר רק מעל סף fluence מסוים.', 'אנרגיה ליחידת שטח'],
  'ablation': ['הסרת חומר באידוי מקומי בפולס לייזר.', 'אידוי חומר בלייזר'],
  'registration': ['התאמה בין קואורדינטות: בין התכנון לפאנל, או בין המצלמה ללייזר.', 'התאמת קואורדינטות'],
  'fiducial': ['סימן יישור מודפס על הפאנל. המכונה מודדת אותו כדי לחשב את המיקום, קנה המידה והסיבוב של הפאנל.', 'סימן יישור'],
