/* guided step for systems without a bench: open the component simulation */
const _showSysK = showSys;
showSys = function (id, step) {
  _showSysK(id, step);
  const x = SYSX[id || 'interlock'];
  if ((step === 'guided') && x && x.comp) {
    const gb = document.getElementById('gb');
    if (gb) { gb.innerHTML = ''; active = bench(COMPONENTS.find(c => c.id === x.comp), gb); }
  }
};

