function defectSVG(kind) {
  const T = (y) => `<rect x="10" y="${y}" width="160" height="16" class="fill-mech"/>`;
  let s = T(14) + T(50), lab = { short: 'Short', open: 'Open', nick: 'Nick', prot: 'Protrusion', pin: 'Pinhole', isl: 'Island' }[kind];
  if (kind === 'short') s += `<rect x="80" y="30" width="14" height="20" class="fill-fault"/>`;
  if (kind === 'open') s = `<rect x="10" y="14" width="68" height="16" class="fill-mech"/><rect x="96" y="14" width="74" height="16" class="fill-mech"/>` + T(50) + `<rect x="78" y="14" width="18" height="16" fill="none" class="faults" stroke-dasharray="3 2"/>`;
  if (kind === 'nick') s += `<path d="M70 30 Q86 20 102 30Z" class="fill-bg"/><path d="M70 30 Q86 20 102 30" class="faults"/>`;
  if (kind === 'prot') s += `<path d="M76 30 Q88 44 100 30Z" class="fill-fault"/>`;
  if (kind === 'pin') s += `<circle cx="88" cy="22" r="4" class="fill-bg"/><circle cx="88" cy="22" r="4" class="faults"/>`;
  if (kind === 'isl') s += `<circle cx="130" cy="40" r="4" class="fill-fault"/>`;
  return SVG(180, 80, s + `<text x="90" y="78" class="lblb" text-anchor="middle">${lab}</text>`, lab);
}
